@firestore.transactional
def executar_transferencia(transaction, ref_origem, ref_destino, valor):
    doc_origem = ref_origem.get(transaction=transaction)
    if not doc_origem.exists or doc_origem.to_dict().get('saldo', 0) < valor:
        raise Exception('saldo-insuficiente-ou-conta-invalida')
    transaction.update(ref_origem, {'saldo': doc_origem.to_dict()['saldo'] - valor})
